module forcad_test_nurbs_curve

    use, intrinsic :: ieee_arithmetic, only: ieee_is_finite
    use forcad_kinds, only: rk
    use forcad_nurbs_curve, only: nurbs_curve, compute_dTgc
    use forcad_utils, only: rotation, solve, linspace, kron_eye, valid_knot_vector, knot_start, knot_end, &
        active_knots, active_span_count
    use forunittest, only: unit_tests

    implicit none

    private
    public :: run_nurbs_curve_tests

contains

    subroutine forcad_nurbs_curve_0001(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        type(nurbs_curve) :: nurbs, bsp
        real(rk), allocatable :: Xc(:,:)
        real(rk), allocatable :: Wc(:)
        real(rk) :: knot(6)

        allocate(Xc(3, 3))
        Xc(1,:) = [0.0_rk, 0.0_rk, 0.0_rk]
        Xc(2,:) = [1.0_rk, 0.0_rk, 0.0_rk]
        Xc(3,:) = [2.0_rk, 0.0_rk, 0.0_rk]
        allocate(Wc(3))
        Wc = [1.0_rk, 0.9_rk, 0.8_rk]
        knot = [0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk, 1.0_rk]

        call nurbs%set(knot, Xc, Wc)
        call bsp%set(knot, Xc)
        call nurbs%set(degree=nurbs%get_degree(), nc=nurbs%get_nc(), Xc=nurbs%get_Xc(), Wc=nurbs%get_Wc())
        call bsp%set(degree=bsp%get_degree(), nc=bsp%get_nc(), Xc=bsp%get_Xc())
        call nurbs%create(res=23)
        call bsp%create(res=23)
        call nurbs%err%print()
        call bsp%err%print()

        call ut%test(ti)%check(&
            name     = "set(): degree==2",&
            res      = nurbs%get_degree(),&
            expected = 2,&
            msg      = "NURBS degree not 2",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0001


