        call bsp%err%print()

        call ut%test(ti)%check(&
            name     = "basis(res=23): sum(N)=1 rows (B-spline)",&
            res      = all(abs(sum(Tgcb,dim=2)-1.0_rk) <= nurbs_curve_tol),&
            expected = .true.,&
            msg      = "B-spline basis partition of unity violated",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0070


    subroutine forcad_nurbs_curve_0071(ut, ti)
