        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1b)
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1e, elem=[1,3])
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1be, elem=[1,3])
        call nurbs%err%print()
        call bsp%err%print()

        call ut%test(ti)%check(&
            name     = "basis(Xt=0.25, elem subset): local matches dense (NURBS)",&
            res      = maxval(abs(Tgc1e - [Tgc1(1), Tgc1(3)])),&
            expected = 0.0_rk,&
            tol      = nurbs_curve_tol,&
            msg      = "Local NURBS basis values must match dense values.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

