        call bsp%basis(Xt=0.0_rk, Tgc=Tgc1be, elem=[1,2,3])
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1)
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1b)
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1e, elem=[1,3])
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1be, elem=[1,3])

