        call bsp%rotate_Xc(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)

        call nurbs%rotate_Xc(0.0_rk, 0.0_rk, 45.0_rk)
        call nurbs%rotate_Xc(0.0_rk, 0.0_rk, -45.0_rk)
        call bsp%rotate_Xc(0.0_rk, 0.0_rk, 45.0_rk)
        call bsp%rotate_Xc(0.0_rk, 0.0_rk, -45.0_rk)
        call nurbs%err%print()
        call bsp%err%print()

