            expected = Xg,&
            tol      = nurbs_curve_tol,&
            msg      = "NURBS Xg changed after X-axis rotation",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0099


