        inquire(file=nurbs_curve_fXth_nurbs, exist=okXth_nurbs)
        inquire(file=nurbs_curve_fIgs_nurbs, exist=okIges_nurbs)
        inquire(file=nurbs_curve_fXc_bsp, exist=okXc_bsp)
        inquire(file=nurbs_curve_fXg_bsp, exist=okXg_bsp)
        inquire(file=nurbs_curve_fXth_bsp, exist=okXth_bsp)
        inquire(file=nurbs_curve_fIgs_bsp, exist=okIges_bsp)

        call nurbs%cmp_nc()
        call bsp%cmp_nc()

        elemConn = nurbs%cmp_elem_Xc_vis(2)
        call nurbs%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xc_vis()
        call nurbs%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xc_vis(2)
        call bsp%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xc_vis()
        call bsp%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xg_vis(2)
        call nurbs%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xg_vis()
        call nurbs%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xg_vis(2)
        call bsp%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xg_vis()
        call bsp%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem()
        call nurbs%set_elem(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem()
        call bsp%set_elem(elemConn)
        deallocate(elemConn)

        call nurbs%modify_Xc(Xc(1,1), 1, 1)
        call bsp%modify_Xc(Xc(1,1), 1, 1)
        call nurbs%modify_Wc(Wc(1), 1)
        call nurbs%create()
        call bsp%create()
        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)

        call nurbs%basis(res=23, Tgc=Tgc)
        call bsp%basis(res=23, Tgc=Tgcb)

        call nurbs%basis(Xt=0.0_rk, Tgc=Tgc1)
        call bsp%basis(Xt=0.0_rk, Tgc=Tgc1b)
        call nurbs%basis(Xt=0.0_rk, Tgc=Tgc1e, elem=[1,2,3])
        call bsp%basis(Xt=0.0_rk, Tgc=Tgc1be, elem=[1,2,3])
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1)
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1b)
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1e, elem=[1,3])
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1be, elem=[1,3])

        allocate(Xt(23))
        do i = 1, 23
            Xt(i) = real(i-1,rk) / real(23-1,rk)
        end do
        call nurbs%basis(Xt=Xt, Tgc=Tgc)
        call bsp%basis(Xt=Xt, Tgc=Tgcb)

        call nurbs%derivative(res=23, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative(res=23, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative(Xt=Xt, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative(Xt=Xt, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative(Xt=0.0_rk, dTgc=dTgc1, Tgc=Tgc1)
        call bsp%derivative(Xt=0.0_rk, dTgc=dTgc1b, Tgc=Tgc1b)

        call nurbs%derivative(Xt=0.0_rk, dTgc=dTgc1, Tgc=Tgc1, elem=[1,2,3])
        call bsp%derivative(Xt=0.0_rk, dTgc=dTgc1b, Tgc=Tgc1b, elem=[1,2,3])

        call nurbs%derivative2(res=23, d2Tgc=d2Tgc, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative2(res=23, d2Tgc=d2Tgcb, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative2(Xt=Xt, d2Tgc=d2Tgc, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative2(Xt=Xt, d2Tgc=d2Tgcb, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative2(Xt=0.0_rk, d2Tgc=d2Tgc1, dTgc=dTgc1, Tgc=Tgc1)
        call bsp%derivative2(Xt=0.0_rk, d2Tgc=d2Tgc1b, dTgc=dTgc1b, Tgc=Tgc1b)

        call nurbs%rotate_Xc(45.0_rk, 0.0_rk, 0.0_rk)
        call nurbs%rotate_Xc(-45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xc(45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xc(-45.0_rk, 0.0_rk, 0.0_rk)

        call nurbs%rotate_Xc(0.0_rk, 45.0_rk, 0.0_rk)
        call nurbs%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)

        call nurbs%rotate_Xc(0.0_rk, 0.0_rk, 45.0_rk)
        call nurbs%rotate_Xc(0.0_rk, 0.0_rk, -45.0_rk)
        call bsp%rotate_Xc(0.0_rk, 0.0_rk, 45.0_rk)
        call bsp%rotate_Xc(0.0_rk, 0.0_rk, -45.0_rk)

        call nurbs%rotate_Xg(45.0_rk, 0.0_rk, 0.0_rk)
        call nurbs%rotate_Xg(-45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xg(45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xg(-45.0_rk, 0.0_rk, 0.0_rk)

        call nurbs%rotate_Xg(0.0_rk, 45.0_rk, 0.0_rk)
        call nurbs%rotate_Xg(0.0_rk, -45.0_rk, 0.0_rk)
        call bsp%rotate_Xg(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xg(0.0_rk, -45.0_rk, 0.0_rk)
        call nurbs%err%print()
        call bsp%err%print()

        call ut%test(ti)%check(&
            name     = "rotate_Xg(Y-axis): geometry preserved (B-spline)",&
            res      = bsp%get_Xg(),&
            expected = Xgb,&
            tol      = nurbs_curve_tol,&
            msg      = "B-spline Xg changed after Y-axis rotation",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0102


    subroutine forcad_nurbs_curve_0103(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: nurbs_curve_tol = 1.0e-5_rk
        character(len=*), parameter :: nurbs_curve_fXc_nurbs = "vtk/test_nurbs_curve_Xc.vtk"
        character(len=*), parameter :: nurbs_curve_fXg_nurbs = "vtk/test_nurbs_curve_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fXth_nurbs = "vtk/test_nurbs_curve_Xth.vtk"
        character(len=*), parameter :: nurbs_curve_fXthXg_nurbs = "vtk/test_nurbs_curve_Xth_in_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fIgs_nurbs = "iges/test_nurbs_curve.iges"
        character(len=*), parameter :: nurbs_curve_fXc_bsp = "vtk/test_bsp_curve_Xc.vtk"
        character(len=*), parameter :: nurbs_curve_fXg_bsp = "vtk/test_bsp_curve_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fXth_bsp = "vtk/test_bsp_curve_Xth.vtk"
        character(len=*), parameter :: nurbs_curve_fXthXg_bsp = "vtk/test_bsp_curve_Xth_in_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fIgs_bsp = "iges/test_bsp_curve.iges"
        integer :: i
        type(nurbs_curve) :: nurbs, bsp
        real(rk), allocatable :: Xc(:,:), Wc(:), Xg(:,:), Xgb(:,:), Xt(:)
        real(rk), allocatable :: Tgc(:,:), dTgc(:,:), Tgcb(:,:), dTgcb(:,:), d2Tgc(:,:), d2Tgcb(:,:)
        real(rk), allocatable :: Tgc1(:), dTgc1(:), Tgc1b(:), dTgc1b(:), d2Tgc1(:), d2Tgc1b(:)
        real(rk), allocatable :: Tgc1e(:), Tgc1be(:)
        integer, allocatable :: elemConn(:,:)
        real(rk) :: knot(6), nearest_Xg(3), nearest_Xt, length, lengthb
        integer :: id
        logical :: okXc_nurbs, okXg_nurbs, okXth_nurbs, okXthXg_nurbs, okIges_nurbs
        logical :: okXc_bsp, okXg_bsp, okXth_bsp, okXthXg_bsp, okIges_bsp

        allocate(Xc(3, 3))
        Xc(1,:) = [0.0_rk, 0.0_rk, 0.0_rk]
        Xc(2,:) = [1.0_rk, 0.0_rk, 0.0_rk]
        Xc(3,:) = [2.0_rk, 0.0_rk, 0.0_rk]
        allocate(Wc(3))
        Wc = [1.0_rk, 0.9_rk, 0.8_rk]
        knot = [0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk, 1.0_rk]

        call nurbs%set(knot, Xc, Wc)
        call bsp%set(knot, Xc)
        call nurbs%set(degree=nurbs%get_degree(), nc=nurbs%get_nc(), Xc=nurbs%get_Xc(), Wc=nurbs%get_Wc())
        call bsp%set(degree=bsp%get_degree(), nc=bsp%get_nc(), Xc=bsp%get_Xc())
        call nurbs%create(res=23)
        call bsp%create(res=23)

        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)
        call nurbs%export_Xth(nurbs_curve_fXth_nurbs)
        call bsp%export_Xth(nurbs_curve_fXth_bsp)
        call nurbs%export_Xth_in_Xg(nurbs_curve_fXthXg_nurbs, res=7)
        call bsp%export_Xth_in_Xg(nurbs_curve_fXthXg_bsp, res=7)
        call nurbs%export_iges(nurbs_curve_fIgs_nurbs)
        call bsp%export_iges(nurbs_curve_fIgs_bsp)
        inquire(file=nurbs_curve_fXc_nurbs, exist=okXc_nurbs)
        inquire(file=nurbs_curve_fXg_nurbs, exist=okXg_nurbs)
        inquire(file=nurbs_curve_fXth_nurbs, exist=okXth_nurbs)
        inquire(file=nurbs_curve_fXthXg_nurbs, exist=okXthXg_nurbs)
        inquire(file=nurbs_curve_fIgs_nurbs, exist=okIges_nurbs)
        inquire(file=nurbs_curve_fXc_bsp, exist=okXc_bsp)
        inquire(file=nurbs_curve_fXg_bsp, exist=okXg_bsp)
        inquire(file=nurbs_curve_fXth_bsp, exist=okXth_bsp)
        inquire(file=nurbs_curve_fXthXg_bsp, exist=okXthXg_bsp)
        inquire(file=nurbs_curve_fIgs_bsp, exist=okIges_bsp)

        call nurbs%cmp_length(length)
        call bsp%cmp_length(lengthb)

        call nurbs%nearest_point([0.0_rk, 0.0_rk, 0.5_rk], nearest_Xg, nearest_Xt, id)

        call bsp%nearest_point([0.0_rk, 0.0_rk, 0.5_rk], nearest_Xg, nearest_Xt, id)

        call nurbs%nearest_point2([0.0_rk, 0.0_rk, 0.5_rk], 1.0e-10_rk, 10, nearest_Xt, nearest_Xg)

        call bsp%nearest_point2([0.0_rk, 0.0_rk, 0.5_rk], 1.0e-10_rk, 10, nearest_Xt, nearest_Xg)

        Xg = nurbs%get_Xg()
        Xgb = bsp%get_Xg()

        call nurbs%set([0.0_rk, 1.0_rk], 2, [-1, -1], Xc, Wc)
        call bsp%set([0.0_rk, 1.0_rk], 2, [-1, -1], Xc)
        call nurbs%create(res=23)
        call bsp%create(res=23)

        call nurbs%set(Xc, Wc)
        call bsp%set(Xc)
        call nurbs%create(res=23)
        call bsp%create(res=23)

        call nurbs%create(Xt=nurbs%get_Xt())
        call bsp%create(Xt=bsp%get_Xt())

        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)
        call nurbs%export_Xth(nurbs_curve_fXth_nurbs)
        call bsp%export_Xth(nurbs_curve_fXth_bsp)
        call nurbs%export_iges(nurbs_curve_fIgs_nurbs)
        call bsp%export_iges(nurbs_curve_fIgs_bsp)
        inquire(file=nurbs_curve_fXc_nurbs, exist=okXc_nurbs)
        inquire(file=nurbs_curve_fXg_nurbs, exist=okXg_nurbs)
        inquire(file=nurbs_curve_fXth_nurbs, exist=okXth_nurbs)
        inquire(file=nurbs_curve_fIgs_nurbs, exist=okIges_nurbs)
        inquire(file=nurbs_curve_fXc_bsp, exist=okXc_bsp)
        inquire(file=nurbs_curve_fXg_bsp, exist=okXg_bsp)
        inquire(file=nurbs_curve_fXth_bsp, exist=okXth_bsp)
        inquire(file=nurbs_curve_fIgs_bsp, exist=okIges_bsp)

        call nurbs%cmp_nc()
        call bsp%cmp_nc()

        elemConn = nurbs%cmp_elem_Xc_vis(2)
        call nurbs%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xc_vis()
        call nurbs%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xc_vis(2)
        call bsp%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xc_vis()
        call bsp%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xg_vis(2)
        call nurbs%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xg_vis()
        call nurbs%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xg_vis(2)
        call bsp%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xg_vis()
        call bsp%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem()
        call nurbs%set_elem(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem()
        call bsp%set_elem(elemConn)
        deallocate(elemConn)

        call nurbs%modify_Xc(Xc(1,1), 1, 1)
        call bsp%modify_Xc(Xc(1,1), 1, 1)
        call nurbs%modify_Wc(Wc(1), 1)
        call nurbs%create()
        call bsp%create()
        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)

        call nurbs%basis(res=23, Tgc=Tgc)
        call bsp%basis(res=23, Tgc=Tgcb)

        call nurbs%basis(Xt=0.0_rk, Tgc=Tgc1)
        call bsp%basis(Xt=0.0_rk, Tgc=Tgc1b)
        call nurbs%basis(Xt=0.0_rk, Tgc=Tgc1e, elem=[1,2,3])
        call bsp%basis(Xt=0.0_rk, Tgc=Tgc1be, elem=[1,2,3])
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1)
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1b)
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1e, elem=[1,3])
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1be, elem=[1,3])

        allocate(Xt(23))
        do i = 1, 23
            Xt(i) = real(i-1,rk) / real(23-1,rk)
        end do
        call nurbs%basis(Xt=Xt, Tgc=Tgc)
        call bsp%basis(Xt=Xt, Tgc=Tgcb)

        call nurbs%derivative(res=23, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative(res=23, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative(Xt=Xt, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative(Xt=Xt, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative(Xt=0.0_rk, dTgc=dTgc1, Tgc=Tgc1)
        call bsp%derivative(Xt=0.0_rk, dTgc=dTgc1b, Tgc=Tgc1b)

        call nurbs%derivative(Xt=0.0_rk, dTgc=dTgc1, Tgc=Tgc1, elem=[1,2,3])
        call bsp%derivative(Xt=0.0_rk, dTgc=dTgc1b, Tgc=Tgc1b, elem=[1,2,3])

        call nurbs%derivative2(res=23, d2Tgc=d2Tgc, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative2(res=23, d2Tgc=d2Tgcb, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative2(Xt=Xt, d2Tgc=d2Tgc, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative2(Xt=Xt, d2Tgc=d2Tgcb, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative2(Xt=0.0_rk, d2Tgc=d2Tgc1, dTgc=dTgc1, Tgc=Tgc1)
        call bsp%derivative2(Xt=0.0_rk, d2Tgc=d2Tgc1b, dTgc=dTgc1b, Tgc=Tgc1b)

        call nurbs%rotate_Xc(45.0_rk, 0.0_rk, 0.0_rk)
        call nurbs%rotate_Xc(-45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xc(45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xc(-45.0_rk, 0.0_rk, 0.0_rk)

        call nurbs%rotate_Xc(0.0_rk, 45.0_rk, 0.0_rk)
        call nurbs%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)

        call nurbs%rotate_Xc(0.0_rk, 0.0_rk, 45.0_rk)
        call nurbs%rotate_Xc(0.0_rk, 0.0_rk, -45.0_rk)
        call bsp%rotate_Xc(0.0_rk, 0.0_rk, 45.0_rk)
        call bsp%rotate_Xc(0.0_rk, 0.0_rk, -45.0_rk)

        call nurbs%rotate_Xg(45.0_rk, 0.0_rk, 0.0_rk)
        call nurbs%rotate_Xg(-45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xg(45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xg(-45.0_rk, 0.0_rk, 0.0_rk)

        call nurbs%rotate_Xg(0.0_rk, 45.0_rk, 0.0_rk)
        call nurbs%rotate_Xg(0.0_rk, -45.0_rk, 0.0_rk)
        call bsp%rotate_Xg(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xg(0.0_rk, -45.0_rk, 0.0_rk)

        call nurbs%rotate_Xg(0.0_rk, 0.0_rk, 45.0_rk)
        call nurbs%rotate_Xg(0.0_rk, 0.0_rk, -45.0_rk)
        call bsp%rotate_Xg(0.0_rk, 0.0_rk, 45.0_rk)
        call bsp%rotate_Xg(0.0_rk, 0.0_rk, -45.0_rk)
        call nurbs%err%print()
        call bsp%err%print()

        call ut%test(ti)%check(&
            name     = "rotate_Xg(Z-axis): geometry preserved (NURBS)",&
            res      = nurbs%get_Xg(),&
            expected = Xg,&
            tol      = nurbs_curve_tol,&
            msg      = "NURBS Xg changed after Z-axis rotation",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0103


    subroutine forcad_nurbs_curve_0104(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: nurbs_curve_tol = 1.0e-5_rk
        character(len=*), parameter :: nurbs_curve_fXc_nurbs = "vtk/test_nurbs_curve_Xc.vtk"
        character(len=*), parameter :: nurbs_curve_fXg_nurbs = "vtk/test_nurbs_curve_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fXth_nurbs = "vtk/test_nurbs_curve_Xth.vtk"
        character(len=*), parameter :: nurbs_curve_fXthXg_nurbs = "vtk/test_nurbs_curve_Xth_in_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fIgs_nurbs = "iges/test_nurbs_curve.iges"
        character(len=*), parameter :: nurbs_curve_fXc_bsp = "vtk/test_bsp_curve_Xc.vtk"
        character(len=*), parameter :: nurbs_curve_fXg_bsp = "vtk/test_bsp_curve_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fXth_bsp = "vtk/test_bsp_curve_Xth.vtk"
        character(len=*), parameter :: nurbs_curve_fXthXg_bsp = "vtk/test_bsp_curve_Xth_in_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fIgs_bsp = "iges/test_bsp_curve.iges"
        integer :: i
        type(nurbs_curve) :: nurbs, bsp
        real(rk), allocatable :: Xc(:,:), Wc(:), Xg(:,:), Xgb(:,:), Xt(:)
        real(rk), allocatable :: Tgc(:,:), dTgc(:,:), Tgcb(:,:), dTgcb(:,:), d2Tgc(:,:), d2Tgcb(:,:)
        real(rk), allocatable :: Tgc1(:), dTgc1(:), Tgc1b(:), dTgc1b(:), d2Tgc1(:), d2Tgc1b(:)
        real(rk), allocatable :: Tgc1e(:), Tgc1be(:)
        integer, allocatable :: elemConn(:,:)
        real(rk) :: knot(6), nearest_Xg(3), nearest_Xt, length, lengthb
        integer :: id
        logical :: okXc_nurbs, okXg_nurbs, okXth_nurbs, okXthXg_nurbs, okIges_nurbs
        logical :: okXc_bsp, okXg_bsp, okXth_bsp, okXthXg_bsp, okIges_bsp

        allocate(Xc(3, 3))
        Xc(1,:) = [0.0_rk, 0.0_rk, 0.0_rk]
        Xc(2,:) = [1.0_rk, 0.0_rk, 0.0_rk]
        Xc(3,:) = [2.0_rk, 0.0_rk, 0.0_rk]
        allocate(Wc(3))
        Wc = [1.0_rk, 0.9_rk, 0.8_rk]
        knot = [0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk, 1.0_rk]

        call nurbs%set(knot, Xc, Wc)
        call bsp%set(knot, Xc)
        call nurbs%set(degree=nurbs%get_degree(), nc=nurbs%get_nc(), Xc=nurbs%get_Xc(), Wc=nurbs%get_Wc())
        call bsp%set(degree=bsp%get_degree(), nc=bsp%get_nc(), Xc=bsp%get_Xc())
        call nurbs%create(res=23)
        call bsp%create(res=23)

        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)
        call nurbs%export_Xth(nurbs_curve_fXth_nurbs)
        call bsp%export_Xth(nurbs_curve_fXth_bsp)
        call nurbs%export_Xth_in_Xg(nurbs_curve_fXthXg_nurbs, res=7)
        call bsp%export_Xth_in_Xg(nurbs_curve_fXthXg_bsp, res=7)
        call nurbs%export_iges(nurbs_curve_fIgs_nurbs)
        call bsp%export_iges(nurbs_curve_fIgs_bsp)
        inquire(file=nurbs_curve_fXc_nurbs, exist=okXc_nurbs)
        inquire(file=nurbs_curve_fXg_nurbs, exist=okXg_nurbs)
        inquire(file=nurbs_curve_fXth_nurbs, exist=okXth_nurbs)
        inquire(file=nurbs_curve_fXthXg_nurbs, exist=okXthXg_nurbs)
        inquire(file=nurbs_curve_fIgs_nurbs, exist=okIges_nurbs)
        inquire(file=nurbs_curve_fXc_bsp, exist=okXc_bsp)
        inquire(file=nurbs_curve_fXg_bsp, exist=okXg_bsp)
        inquire(file=nurbs_curve_fXth_bsp, exist=okXth_bsp)
        inquire(file=nurbs_curve_fXthXg_bsp, exist=okXthXg_bsp)
        inquire(file=nurbs_curve_fIgs_bsp, exist=okIges_bsp)

        call nurbs%cmp_length(length)
        call bsp%cmp_length(lengthb)

        call nurbs%nearest_point([0.0_rk, 0.0_rk, 0.5_rk], nearest_Xg, nearest_Xt, id)

        call bsp%nearest_point([0.0_rk, 0.0_rk, 0.5_rk], nearest_Xg, nearest_Xt, id)

        call nurbs%nearest_point2([0.0_rk, 0.0_rk, 0.5_rk], 1.0e-10_rk, 10, nearest_Xt, nearest_Xg)

        call bsp%nearest_point2([0.0_rk, 0.0_rk, 0.5_rk], 1.0e-10_rk, 10, nearest_Xt, nearest_Xg)

        Xg = nurbs%get_Xg()
        Xgb = bsp%get_Xg()

        call nurbs%set([0.0_rk, 1.0_rk], 2, [-1, -1], Xc, Wc)
        call bsp%set([0.0_rk, 1.0_rk], 2, [-1, -1], Xc)
        call nurbs%create(res=23)
        call bsp%create(res=23)

        call nurbs%set(Xc, Wc)
        call bsp%set(Xc)
        call nurbs%create(res=23)
        call bsp%create(res=23)

        call nurbs%create(Xt=nurbs%get_Xt())
        call bsp%create(Xt=bsp%get_Xt())

        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)
        call nurbs%export_Xth(nurbs_curve_fXth_nurbs)
        call bsp%export_Xth(nurbs_curve_fXth_bsp)
        call nurbs%export_iges(nurbs_curve_fIgs_nurbs)
        call bsp%export_iges(nurbs_curve_fIgs_bsp)
        inquire(file=nurbs_curve_fXc_nurbs, exist=okXc_nurbs)
        inquire(file=nurbs_curve_fXg_nurbs, exist=okXg_nurbs)
        inquire(file=nurbs_curve_fXth_nurbs, exist=okXth_nurbs)
        inquire(file=nurbs_curve_fIgs_nurbs, exist=okIges_nurbs)
        inquire(file=nurbs_curve_fXc_bsp, exist=okXc_bsp)
        inquire(file=nurbs_curve_fXg_bsp, exist=okXg_bsp)
        inquire(file=nurbs_curve_fXth_bsp, exist=okXth_bsp)
        inquire(file=nurbs_curve_fIgs_bsp, exist=okIges_bsp)

        call nurbs%cmp_nc()
        call bsp%cmp_nc()

        elemConn = nurbs%cmp_elem_Xc_vis(2)
        call nurbs%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xc_vis()
        call nurbs%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xc_vis(2)
        call bsp%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xc_vis()
        call bsp%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xg_vis(2)
        call nurbs%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xg_vis()
        call nurbs%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xg_vis(2)
        call bsp%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xg_vis()
        call bsp%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem()
        call nurbs%set_elem(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem()
        call bsp%set_elem(elemConn)
        deallocate(elemConn)

        call nurbs%modify_Xc(Xc(1,1), 1, 1)
        call bsp%modify_Xc(Xc(1,1), 1, 1)
        call nurbs%modify_Wc(Wc(1), 1)
        call nurbs%create()
        call bsp%create()
        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)

        call nurbs%basis(res=23, Tgc=Tgc)
        call bsp%basis(res=23, Tgc=Tgcb)

        call nurbs%basis(Xt=0.0_rk, Tgc=Tgc1)
        call bsp%basis(Xt=0.0_rk, Tgc=Tgc1b)
        call nurbs%basis(Xt=0.0_rk, Tgc=Tgc1e, elem=[1,2,3])
        call bsp%basis(Xt=0.0_rk, Tgc=Tgc1be, elem=[1,2,3])
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1)
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1b)
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1e, elem=[1,3])
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1be, elem=[1,3])

        allocate(Xt(23))
        do i = 1, 23
            Xt(i) = real(i-1,rk) / real(23-1,rk)
        end do
        call nurbs%basis(Xt=Xt, Tgc=Tgc)
        call bsp%basis(Xt=Xt, Tgc=Tgcb)

        call nurbs%derivative(res=23, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative(res=23, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative(Xt=Xt, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative(Xt=Xt, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative(Xt=0.0_rk, dTgc=dTgc1, Tgc=Tgc1)
        call bsp%derivative(Xt=0.0_rk, dTgc=dTgc1b, Tgc=Tgc1b)

        call nurbs%derivative(Xt=0.0_rk, dTgc=dTgc1, Tgc=Tgc1, elem=[1,2,3])
        call bsp%derivative(Xt=0.0_rk, dTgc=dTgc1b, Tgc=Tgc1b, elem=[1,2,3])

        call nurbs%derivative2(res=23, d2Tgc=d2Tgc, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative2(res=23, d2Tgc=d2Tgcb, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative2(Xt=Xt, d2Tgc=d2Tgc, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative2(Xt=Xt, d2Tgc=d2Tgcb, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative2(Xt=0.0_rk, d2Tgc=d2Tgc1, dTgc=dTgc1, Tgc=Tgc1)
        call bsp%derivative2(Xt=0.0_rk, d2Tgc=d2Tgc1b, dTgc=dTgc1b, Tgc=Tgc1b)

        call nurbs%rotate_Xc(45.0_rk, 0.0_rk, 0.0_rk)
        call nurbs%rotate_Xc(-45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xc(45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xc(-45.0_rk, 0.0_rk, 0.0_rk)

        call nurbs%rotate_Xc(0.0_rk, 45.0_rk, 0.0_rk)
        call nurbs%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)

        call nurbs%rotate_Xc(0.0_rk, 0.0_rk, 45.0_rk)
        call nurbs%rotate_Xc(0.0_rk, 0.0_rk, -45.0_rk)
        call bsp%rotate_Xc(0.0_rk, 0.0_rk, 45.0_rk)
        call bsp%rotate_Xc(0.0_rk, 0.0_rk, -45.0_rk)

        call nurbs%rotate_Xg(45.0_rk, 0.0_rk, 0.0_rk)
        call nurbs%rotate_Xg(-45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xg(45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xg(-45.0_rk, 0.0_rk, 0.0_rk)

        call nurbs%rotate_Xg(0.0_rk, 45.0_rk, 0.0_rk)
        call nurbs%rotate_Xg(0.0_rk, -45.0_rk, 0.0_rk)
        call bsp%rotate_Xg(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xg(0.0_rk, -45.0_rk, 0.0_rk)

        call nurbs%rotate_Xg(0.0_rk, 0.0_rk, 45.0_rk)
        call nurbs%rotate_Xg(0.0_rk, 0.0_rk, -45.0_rk)
        call bsp%rotate_Xg(0.0_rk, 0.0_rk, 45.0_rk)
        call bsp%rotate_Xg(0.0_rk, 0.0_rk, -45.0_rk)
        call nurbs%err%print()
        call bsp%err%print()

        call ut%test(ti)%check(&
            name     = "rotate_Xg(Z-axis): geometry preserved (B-spline)",&
            res      = bsp%get_Xg(),&
            expected = Xgb,&
            tol      = nurbs_curve_tol,&
            msg      = "B-spline Xg changed after Z-axis rotation",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0104


    subroutine forcad_nurbs_curve_0105(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: nurbs_curve_tol = 1.0e-5_rk
        character(len=*), parameter :: nurbs_curve_fXc_nurbs = "vtk/test_nurbs_curve_Xc.vtk"
        character(len=*), parameter :: nurbs_curve_fXg_nurbs = "vtk/test_nurbs_curve_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fXth_nurbs = "vtk/test_nurbs_curve_Xth.vtk"
        character(len=*), parameter :: nurbs_curve_fXthXg_nurbs = "vtk/test_nurbs_curve_Xth_in_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fIgs_nurbs = "iges/test_nurbs_curve.iges"
        character(len=*), parameter :: nurbs_curve_fXc_bsp = "vtk/test_bsp_curve_Xc.vtk"
        character(len=*), parameter :: nurbs_curve_fXg_bsp = "vtk/test_bsp_curve_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fXth_bsp = "vtk/test_bsp_curve_Xth.vtk"
        character(len=*), parameter :: nurbs_curve_fXthXg_bsp = "vtk/test_bsp_curve_Xth_in_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fIgs_bsp = "iges/test_bsp_curve.iges"
        integer :: i
        type(nurbs_curve) :: nurbs, bsp
        real(rk), allocatable :: Xc(:,:), Wc(:), Xg(:,:), Xgb(:,:), Xt(:)
        real(rk), allocatable :: Tgc(:,:), dTgc(:,:), Tgcb(:,:), dTgcb(:,:), d2Tgc(:,:), d2Tgcb(:,:)
        real(rk), allocatable :: Tgc1(:), dTgc1(:), Tgc1b(:), dTgc1b(:), d2Tgc1(:), d2Tgc1b(:)
        real(rk), allocatable :: Tgc1e(:), Tgc1be(:)
        integer, allocatable :: elemConn(:,:)
        real(rk) :: knot(6), nearest_Xg(3), nearest_Xt, length, lengthb
        integer :: id
        logical :: okXc_nurbs, okXg_nurbs, okXth_nurbs, okXthXg_nurbs, okIges_nurbs
        logical :: okXc_bsp, okXg_bsp, okXth_bsp, okXthXg_bsp, okIges_bsp

        allocate(Xc(3, 3))
        Xc(1,:) = [0.0_rk, 0.0_rk, 0.0_rk]
        Xc(2,:) = [1.0_rk, 0.0_rk, 0.0_rk]
        Xc(3,:) = [2.0_rk, 0.0_rk, 0.0_rk]
        allocate(Wc(3))
        Wc = [1.0_rk, 0.9_rk, 0.8_rk]
        knot = [0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk, 1.0_rk]

        call nurbs%set(knot, Xc, Wc)
        call bsp%set(knot, Xc)
        call nurbs%set(degree=nurbs%get_degree(), nc=nurbs%get_nc(), Xc=nurbs%get_Xc(), Wc=nurbs%get_Wc())
        call bsp%set(degree=bsp%get_degree(), nc=bsp%get_nc(), Xc=bsp%get_Xc())
        call nurbs%create(res=23)
        call bsp%create(res=23)

        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)
        call nurbs%export_Xth(nurbs_curve_fXth_nurbs)
        call bsp%export_Xth(nurbs_curve_fXth_bsp)
        call nurbs%export_Xth_in_Xg(nurbs_curve_fXthXg_nurbs, res=7)
        call bsp%export_Xth_in_Xg(nurbs_curve_fXthXg_bsp, res=7)
        call nurbs%export_iges(nurbs_curve_fIgs_nurbs)
        call bsp%export_iges(nurbs_curve_fIgs_bsp)
        inquire(file=nurbs_curve_fXc_nurbs, exist=okXc_nurbs)
        inquire(file=nurbs_curve_fXg_nurbs, exist=okXg_nurbs)
        inquire(file=nurbs_curve_fXth_nurbs, exist=okXth_nurbs)
        inquire(file=nurbs_curve_fXthXg_nurbs, exist=okXthXg_nurbs)
        inquire(file=nurbs_curve_fIgs_nurbs, exist=okIges_nurbs)
        inquire(file=nurbs_curve_fXc_bsp, exist=okXc_bsp)
        inquire(file=nurbs_curve_fXg_bsp, exist=okXg_bsp)
        inquire(file=nurbs_curve_fXth_bsp, exist=okXth_bsp)
        inquire(file=nurbs_curve_fXthXg_bsp, exist=okXthXg_bsp)
        inquire(file=nurbs_curve_fIgs_bsp, exist=okIges_bsp)

        call nurbs%cmp_length(length)
        call bsp%cmp_length(lengthb)

        call nurbs%nearest_point([0.0_rk, 0.0_rk, 0.5_rk], nearest_Xg, nearest_Xt, id)

        call bsp%nearest_point([0.0_rk, 0.0_rk, 0.5_rk], nearest_Xg, nearest_Xt, id)

        call nurbs%nearest_point2([0.0_rk, 0.0_rk, 0.5_rk], 1.0e-10_rk, 10, nearest_Xt, nearest_Xg)

        call bsp%nearest_point2([0.0_rk, 0.0_rk, 0.5_rk], 1.0e-10_rk, 10, nearest_Xt, nearest_Xg)

        Xg = nurbs%get_Xg()
        Xgb = bsp%get_Xg()

        call nurbs%set([0.0_rk, 1.0_rk], 2, [-1, -1], Xc, Wc)
        call bsp%set([0.0_rk, 1.0_rk], 2, [-1, -1], Xc)
        call nurbs%create(res=23)
        call bsp%create(res=23)

        call nurbs%set(Xc, Wc)
        call bsp%set(Xc)
        call nurbs%create(res=23)
        call bsp%create(res=23)

        call nurbs%create(Xt=nurbs%get_Xt())
        call bsp%create(Xt=bsp%get_Xt())

        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)
        call nurbs%export_Xth(nurbs_curve_fXth_nurbs)
        call bsp%export_Xth(nurbs_curve_fXth_bsp)
        call nurbs%export_iges(nurbs_curve_fIgs_nurbs)
        call bsp%export_iges(nurbs_curve_fIgs_bsp)
        inquire(file=nurbs_curve_fXc_nurbs, exist=okXc_nurbs)
        inquire(file=nurbs_curve_fXg_nurbs, exist=okXg_nurbs)
        inquire(file=nurbs_curve_fXth_nurbs, exist=okXth_nurbs)
        inquire(file=nurbs_curve_fIgs_nurbs, exist=okIges_nurbs)
        inquire(file=nurbs_curve_fXc_bsp, exist=okXc_bsp)
        inquire(file=nurbs_curve_fXg_bsp, exist=okXg_bsp)
        inquire(file=nurbs_curve_fXth_bsp, exist=okXth_bsp)
        inquire(file=nurbs_curve_fIgs_bsp, exist=okIges_bsp)

        call nurbs%cmp_nc()
        call bsp%cmp_nc()

        elemConn = nurbs%cmp_elem_Xc_vis(2)
        call nurbs%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xc_vis()
        call nurbs%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xc_vis(2)
        call bsp%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xc_vis()
        call bsp%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xg_vis(2)
        call nurbs%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xg_vis()
        call nurbs%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xg_vis(2)
        call bsp%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xg_vis()
        call bsp%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem()
        call nurbs%set_elem(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem()
        call bsp%set_elem(elemConn)
        deallocate(elemConn)

        call nurbs%modify_Xc(Xc(1,1), 1, 1)
        call bsp%modify_Xc(Xc(1,1), 1, 1)
        call nurbs%modify_Wc(Wc(1), 1)
        call nurbs%create()
        call bsp%create()
        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)

        call nurbs%basis(res=23, Tgc=Tgc)
        call bsp%basis(res=23, Tgc=Tgcb)

        call nurbs%basis(Xt=0.0_rk, Tgc=Tgc1)
        call bsp%basis(Xt=0.0_rk, Tgc=Tgc1b)
        call nurbs%basis(Xt=0.0_rk, Tgc=Tgc1e, elem=[1,2,3])
        call bsp%basis(Xt=0.0_rk, Tgc=Tgc1be, elem=[1,2,3])
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1)
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1b)
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1e, elem=[1,3])
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1be, elem=[1,3])

        allocate(Xt(23))
        do i = 1, 23
            Xt(i) = real(i-1,rk) / real(23-1,rk)
        end do
        call nurbs%basis(Xt=Xt, Tgc=Tgc)
        call bsp%basis(Xt=Xt, Tgc=Tgcb)

        call nurbs%derivative(res=23, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative(res=23, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative(Xt=Xt, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative(Xt=Xt, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative(Xt=0.0_rk, dTgc=dTgc1, Tgc=Tgc1)
        call bsp%derivative(Xt=0.0_rk, dTgc=dTgc1b, Tgc=Tgc1b)

        call nurbs%derivative(Xt=0.0_rk, dTgc=dTgc1, Tgc=Tgc1, elem=[1,2,3])
        call bsp%derivative(Xt=0.0_rk, dTgc=dTgc1b, Tgc=Tgc1b, elem=[1,2,3])

        call nurbs%derivative2(res=23, d2Tgc=d2Tgc, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative2(res=23, d2Tgc=d2Tgcb, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative2(Xt=Xt, d2Tgc=d2Tgc, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative2(Xt=Xt, d2Tgc=d2Tgcb, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative2(Xt=0.0_rk, d2Tgc=d2Tgc1, dTgc=dTgc1, Tgc=Tgc1)
        call bsp%derivative2(Xt=0.0_rk, d2Tgc=d2Tgc1b, dTgc=dTgc1b, Tgc=Tgc1b)

        call nurbs%rotate_Xc(45.0_rk, 0.0_rk, 0.0_rk)
        call nurbs%rotate_Xc(-45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xc(45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xc(-45.0_rk, 0.0_rk, 0.0_rk)

        call nurbs%rotate_Xc(0.0_rk, 45.0_rk, 0.0_rk)
        call nurbs%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)

        call nurbs%rotate_Xc(0.0_rk, 0.0_rk, 45.0_rk)
        call nurbs%rotate_Xc(0.0_rk, 0.0_rk, -45.0_rk)
        call bsp%rotate_Xc(0.0_rk, 0.0_rk, 45.0_rk)
        call bsp%rotate_Xc(0.0_rk, 0.0_rk, -45.0_rk)

        call nurbs%rotate_Xg(45.0_rk, 0.0_rk, 0.0_rk)
        call nurbs%rotate_Xg(-45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xg(45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xg(-45.0_rk, 0.0_rk, 0.0_rk)

        call nurbs%rotate_Xg(0.0_rk, 45.0_rk, 0.0_rk)
        call nurbs%rotate_Xg(0.0_rk, -45.0_rk, 0.0_rk)
        call bsp%rotate_Xg(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xg(0.0_rk, -45.0_rk, 0.0_rk)

        call nurbs%rotate_Xg(0.0_rk, 0.0_rk, 45.0_rk)
        call nurbs%rotate_Xg(0.0_rk, 0.0_rk, -45.0_rk)
        call bsp%rotate_Xg(0.0_rk, 0.0_rk, 45.0_rk)
        call bsp%rotate_Xg(0.0_rk, 0.0_rk, -45.0_rk)

        call nurbs%translate_Xc([5.0_rk, 5.0_rk, 5.0_rk])
        call nurbs%translate_Xc([-5.0_rk, -5.0_rk, -5.0_rk])
        call bsp%translate_Xc([5.0_rk, 5.0_rk, 5.0_rk])
        call bsp%translate_Xc([-5.0_rk, -5.0_rk, -5.0_rk])
        call nurbs%err%print()
        call bsp%err%print()

        call ut%test(ti)%check(&
            name     = "translate_Xc(): geometry preserved (NURBS)",&
            res      = nurbs%get_Xc(),&
            expected = Xc,&
            tol      = nurbs_curve_tol,&
            msg      = "NURBS Xc changed after translation",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0105


    subroutine forcad_nurbs_curve_0106(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: nurbs_curve_tol = 1.0e-5_rk
        character(len=*), parameter :: nurbs_curve_fXc_nurbs = "vtk/test_nurbs_curve_Xc.vtk"
        character(len=*), parameter :: nurbs_curve_fXg_nurbs = "vtk/test_nurbs_curve_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fXth_nurbs = "vtk/test_nurbs_curve_Xth.vtk"
        character(len=*), parameter :: nurbs_curve_fXthXg_nurbs = "vtk/test_nurbs_curve_Xth_in_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fIgs_nurbs = "iges/test_nurbs_curve.iges"
        character(len=*), parameter :: nurbs_curve_fXc_bsp = "vtk/test_bsp_curve_Xc.vtk"
        character(len=*), parameter :: nurbs_curve_fXg_bsp = "vtk/test_bsp_curve_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fXth_bsp = "vtk/test_bsp_curve_Xth.vtk"
        character(len=*), parameter :: nurbs_curve_fXthXg_bsp = "vtk/test_bsp_curve_Xth_in_Xg.vtk"
        character(len=*), parameter :: nurbs_curve_fIgs_bsp = "iges/test_bsp_curve.iges"
        integer :: i
        type(nurbs_curve) :: nurbs, bsp
        real(rk), allocatable :: Xc(:,:), Wc(:), Xg(:,:), Xgb(:,:), Xt(:)
        real(rk), allocatable :: Tgc(:,:), dTgc(:,:), Tgcb(:,:), dTgcb(:,:), d2Tgc(:,:), d2Tgcb(:,:)
        real(rk), allocatable :: Tgc1(:), dTgc1(:), Tgc1b(:), dTgc1b(:), d2Tgc1(:), d2Tgc1b(:)
        real(rk), allocatable :: Tgc1e(:), Tgc1be(:)
        integer, allocatable :: elemConn(:,:)
        real(rk) :: knot(6), nearest_Xg(3), nearest_Xt, length, lengthb
        integer :: id
        logical :: okXc_nurbs, okXg_nurbs, okXth_nurbs, okXthXg_nurbs, okIges_nurbs
        logical :: okXc_bsp, okXg_bsp, okXth_bsp, okXthXg_bsp, okIges_bsp

        allocate(Xc(3, 3))
        Xc(1,:) = [0.0_rk, 0.0_rk, 0.0_rk]
        Xc(2,:) = [1.0_rk, 0.0_rk, 0.0_rk]
        Xc(3,:) = [2.0_rk, 0.0_rk, 0.0_rk]
        allocate(Wc(3))
        Wc = [1.0_rk, 0.9_rk, 0.8_rk]
        knot = [0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk, 1.0_rk]

        call nurbs%set(knot, Xc, Wc)
        call bsp%set(knot, Xc)
        call nurbs%set(degree=nurbs%get_degree(), nc=nurbs%get_nc(), Xc=nurbs%get_Xc(), Wc=nurbs%get_Wc())
        call bsp%set(degree=bsp%get_degree(), nc=bsp%get_nc(), Xc=bsp%get_Xc())
        call nurbs%create(res=23)
        call bsp%create(res=23)

        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)
        call nurbs%export_Xth(nurbs_curve_fXth_nurbs)
        call bsp%export_Xth(nurbs_curve_fXth_bsp)
        call nurbs%export_Xth_in_Xg(nurbs_curve_fXthXg_nurbs, res=7)
        call bsp%export_Xth_in_Xg(nurbs_curve_fXthXg_bsp, res=7)
        call nurbs%export_iges(nurbs_curve_fIgs_nurbs)
        call bsp%export_iges(nurbs_curve_fIgs_bsp)
        inquire(file=nurbs_curve_fXc_nurbs, exist=okXc_nurbs)
        inquire(file=nurbs_curve_fXg_nurbs, exist=okXg_nurbs)
        inquire(file=nurbs_curve_fXth_nurbs, exist=okXth_nurbs)
        inquire(file=nurbs_curve_fXthXg_nurbs, exist=okXthXg_nurbs)
        inquire(file=nurbs_curve_fIgs_nurbs, exist=okIges_nurbs)
        inquire(file=nurbs_curve_fXc_bsp, exist=okXc_bsp)
        inquire(file=nurbs_curve_fXg_bsp, exist=okXg_bsp)
        inquire(file=nurbs_curve_fXth_bsp, exist=okXth_bsp)
        inquire(file=nurbs_curve_fXthXg_bsp, exist=okXthXg_bsp)
        inquire(file=nurbs_curve_fIgs_bsp, exist=okIges_bsp)

        call nurbs%cmp_length(length)
        call bsp%cmp_length(lengthb)

        call nurbs%nearest_point([0.0_rk, 0.0_rk, 0.5_rk], nearest_Xg, nearest_Xt, id)

        call bsp%nearest_point([0.0_rk, 0.0_rk, 0.5_rk], nearest_Xg, nearest_Xt, id)

        call nurbs%nearest_point2([0.0_rk, 0.0_rk, 0.5_rk], 1.0e-10_rk, 10, nearest_Xt, nearest_Xg)

        call bsp%nearest_point2([0.0_rk, 0.0_rk, 0.5_rk], 1.0e-10_rk, 10, nearest_Xt, nearest_Xg)

        Xg = nurbs%get_Xg()
        Xgb = bsp%get_Xg()

        call nurbs%set([0.0_rk, 1.0_rk], 2, [-1, -1], Xc, Wc)
        call bsp%set([0.0_rk, 1.0_rk], 2, [-1, -1], Xc)
        call nurbs%create(res=23)
        call bsp%create(res=23)

        call nurbs%set(Xc, Wc)
        call bsp%set(Xc)
        call nurbs%create(res=23)
        call bsp%create(res=23)

        call nurbs%create(Xt=nurbs%get_Xt())
        call bsp%create(Xt=bsp%get_Xt())

        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)
        call nurbs%export_Xth(nurbs_curve_fXth_nurbs)
        call bsp%export_Xth(nurbs_curve_fXth_bsp)
        call nurbs%export_iges(nurbs_curve_fIgs_nurbs)
        call bsp%export_iges(nurbs_curve_fIgs_bsp)
        inquire(file=nurbs_curve_fXc_nurbs, exist=okXc_nurbs)
        inquire(file=nurbs_curve_fXg_nurbs, exist=okXg_nurbs)
        inquire(file=nurbs_curve_fXth_nurbs, exist=okXth_nurbs)
        inquire(file=nurbs_curve_fIgs_nurbs, exist=okIges_nurbs)
        inquire(file=nurbs_curve_fXc_bsp, exist=okXc_bsp)
        inquire(file=nurbs_curve_fXg_bsp, exist=okXg_bsp)
        inquire(file=nurbs_curve_fXth_bsp, exist=okXth_bsp)
        inquire(file=nurbs_curve_fIgs_bsp, exist=okIges_bsp)

        call nurbs%cmp_nc()
        call bsp%cmp_nc()

        elemConn = nurbs%cmp_elem_Xc_vis(2)
        call nurbs%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xc_vis()
        call nurbs%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xc_vis(2)
        call bsp%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xc_vis()
        call bsp%set_elem_Xc_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xg_vis(2)
        call nurbs%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem_Xg_vis()
        call nurbs%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xg_vis(2)
        call bsp%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem_Xg_vis()
        call bsp%set_elem_Xg_vis(elemConn)
        deallocate(elemConn)
        elemConn = nurbs%cmp_elem()
        call nurbs%set_elem(elemConn)
        deallocate(elemConn)
        elemConn = bsp%cmp_elem()
        call bsp%set_elem(elemConn)
        deallocate(elemConn)

        call nurbs%modify_Xc(Xc(1,1), 1, 1)
        call bsp%modify_Xc(Xc(1,1), 1, 1)
        call nurbs%modify_Wc(Wc(1), 1)
        call nurbs%create()
        call bsp%create()
        call nurbs%export_Xc(nurbs_curve_fXc_nurbs)
        call bsp%export_Xc(nurbs_curve_fXc_bsp)
        call nurbs%export_Xg(nurbs_curve_fXg_nurbs)
        call bsp%export_Xg(nurbs_curve_fXg_bsp)

        call nurbs%basis(res=23, Tgc=Tgc)
        call bsp%basis(res=23, Tgc=Tgcb)

        call nurbs%basis(Xt=0.0_rk, Tgc=Tgc1)
        call bsp%basis(Xt=0.0_rk, Tgc=Tgc1b)
        call nurbs%basis(Xt=0.0_rk, Tgc=Tgc1e, elem=[1,2,3])
        call bsp%basis(Xt=0.0_rk, Tgc=Tgc1be, elem=[1,2,3])
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1)
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1b)
        call nurbs%basis(Xt=0.25_rk, Tgc=Tgc1e, elem=[1,3])
        call bsp%basis(Xt=0.25_rk, Tgc=Tgc1be, elem=[1,3])

        allocate(Xt(23))
        do i = 1, 23
            Xt(i) = real(i-1,rk) / real(23-1,rk)
        end do
        call nurbs%basis(Xt=Xt, Tgc=Tgc)
        call bsp%basis(Xt=Xt, Tgc=Tgcb)

        call nurbs%derivative(res=23, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative(res=23, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative(Xt=Xt, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative(Xt=Xt, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative(Xt=0.0_rk, dTgc=dTgc1, Tgc=Tgc1)
        call bsp%derivative(Xt=0.0_rk, dTgc=dTgc1b, Tgc=Tgc1b)

        call nurbs%derivative(Xt=0.0_rk, dTgc=dTgc1, Tgc=Tgc1, elem=[1,2,3])
        call bsp%derivative(Xt=0.0_rk, dTgc=dTgc1b, Tgc=Tgc1b, elem=[1,2,3])

        call nurbs%derivative2(res=23, d2Tgc=d2Tgc, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative2(res=23, d2Tgc=d2Tgcb, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative2(Xt=Xt, d2Tgc=d2Tgc, dTgc=dTgc, Tgc=Tgc)
        call bsp%derivative2(Xt=Xt, d2Tgc=d2Tgcb, dTgc=dTgcb, Tgc=Tgcb)

        call nurbs%derivative2(Xt=0.0_rk, d2Tgc=d2Tgc1, dTgc=dTgc1, Tgc=Tgc1)
        call bsp%derivative2(Xt=0.0_rk, d2Tgc=d2Tgc1b, dTgc=dTgc1b, Tgc=Tgc1b)

        call nurbs%rotate_Xc(45.0_rk, 0.0_rk, 0.0_rk)
        call nurbs%rotate_Xc(-45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xc(45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xc(-45.0_rk, 0.0_rk, 0.0_rk)

        call nurbs%rotate_Xc(0.0_rk, 45.0_rk, 0.0_rk)
        call nurbs%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xc(0.0_rk, -45.0_rk, 0.0_rk)

        call nurbs%rotate_Xc(0.0_rk, 0.0_rk, 45.0_rk)
        call nurbs%rotate_Xc(0.0_rk, 0.0_rk, -45.0_rk)
        call bsp%rotate_Xc(0.0_rk, 0.0_rk, 45.0_rk)
        call bsp%rotate_Xc(0.0_rk, 0.0_rk, -45.0_rk)

        call nurbs%rotate_Xg(45.0_rk, 0.0_rk, 0.0_rk)
        call nurbs%rotate_Xg(-45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xg(45.0_rk, 0.0_rk, 0.0_rk)
        call bsp%rotate_Xg(-45.0_rk, 0.0_rk, 0.0_rk)

        call nurbs%rotate_Xg(0.0_rk, 45.0_rk, 0.0_rk)
        call nurbs%rotate_Xg(0.0_rk, -45.0_rk, 0.0_rk)
        call bsp%rotate_Xg(0.0_rk, 45.0_rk, 0.0_rk)
        call bsp%rotate_Xg(0.0_rk, -45.0_rk, 0.0_rk)

        call nurbs%rotate_Xg(0.0_rk, 0.0_rk, 45.0_rk)
        call nurbs%rotate_Xg(0.0_rk, 0.0_rk, -45.0_rk)
        call bsp%rotate_Xg(0.0_rk, 0.0_rk, 45.0_rk)
        call bsp%rotate_Xg(0.0_rk, 0.0_rk, -45.0_rk)

        call nurbs%translate_Xc([5.0_rk, 5.0_rk, 5.0_rk])
        call nurbs%translate_Xc([-5.0_rk, -5.0_rk, -5.0_rk])
        call bsp%translate_Xc([5.0_rk, 5.0_rk, 5.0_rk])
        call bsp%translate_Xc([-5.0_rk, -5.0_rk, -5.0_rk])
        call nurbs%err%print()
        call bsp%err%print()

        call ut%test(ti)%check(&
            name     = "translate_Xc(): geometry preserved (B-spline)",&
            res      = bsp%get_Xc(),&
            expected = Xc,&
            tol      = nurbs_curve_tol,&
            msg      = "B-spline Xc changed after translation",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0106


    subroutine forcad_nurbs_curve_0107(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: nurbs_curve_tol = 1.0e-5_rk
        character(len=*), parameter :: nurbs_curve_fXc_nurbs = "vtk/test_nurbs_curve_Xc.vtk"
