        call bsp%translate_Xg([5.0_rk, 5.0_rk, 5.0_rk])
        call bsp%translate_Xg([-5.0_rk, -5.0_rk, -5.0_rk])
        call nurbs%err%print()
        call bsp%err%print()

        call ut%test(ti)%check(&
            name     = "translate_Xg(): geometry preserved (NURBS)",&
            res      = nurbs%get_Xg(),&
            expected = Xg,&
            tol      = nurbs_curve_tol,&
            msg      = "NURBS Xg changed after translation",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0107


    subroutine forcad_nurbs_curve_0108(ut, ti)
