        call nonopen%basis(1.5_rk, Tgc_nonopen)

        call nonopen%derivative(2.5_rk, dTgc_nonopen, Tgc_nonopen, elem=[0, 5])

        call explicit_degree%set(knot_nonopen, Xc_nonopen, degree=2)
        call explicit_degree%basis(2.5_rk, Tgc_nonopen)
        call nonopen%err%print()
        call explicit_degree%err%print()

        call ut%test(ti)%check(&
            name     = "set(): explicit non-open curve degree",&
            res      = merge(1, 0, explicit_degree%err%ok .and. explicit_degree%get_degree() == 2 .and. explicit_degree%get_nc() &
                == 4 .and. abs(sum(Tgc_nonopen) - 1.0_rk) <= nurbs_curve_tol),&
            expected = 1,&
            msg      = "Explicit curve degree should support unclamped knot vectors",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0127


    subroutine forcad_nurbs_curve_0128(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        type(nurbs_curve) :: nonopen, explicit_degree, wrong_degree
        real(rk), allocatable :: Xc_nonopen(:,:), Xt_nonopen(:), Tgc_nonopen(:), dTgc_nonopen(:)
        real(rk) :: knot_nonopen(7)
        integer :: ii

        allocate(Xc_nonopen(4, 3), source=0.0_rk)
        do ii = 1, 4
            Xc_nonopen(ii,1) = real(ii - 1, rk)
        end do
        knot_nonopen = [0.0_rk, 1.0_rk, 2.0_rk, 3.0_rk, 4.0_rk, 5.0_rk, 6.0_rk]

        call nonopen%set(knot_nonopen, Xc_nonopen)
        call nonopen%create(res=5)
        Xt_nonopen = nonopen%get_Xt()

        call nonopen%basis(2.5_rk, Tgc_nonopen)

        call nonopen%basis(1.5_rk, Tgc_nonopen)

        call nonopen%derivative(2.5_rk, dTgc_nonopen, Tgc_nonopen, elem=[0, 5])

        call explicit_degree%set(knot_nonopen, Xc_nonopen, degree=2)
        call explicit_degree%basis(2.5_rk, Tgc_nonopen)

        call wrong_degree%set(knot_nonopen, Xc_nonopen, degree=1)
        call nonopen%err%print()
        call explicit_degree%err%print()
        call wrong_degree%err%print()

        call ut%test(ti)%check(&
            name     = "set(): rejects mismatched explicit curve degree",&
            res      = wrong_degree%err%ok,&
            expected = .false.,&
            msg      = "Explicit curve degree must match size(knot) == nc + degree + 1",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0128


    subroutine forcad_nurbs_curve_0129(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: nurbs_curve_tol = 1.0e-5_rk
        type(nurbs_curve) :: repeated
        real(rk), allocatable :: Xc_repeated(:,:), Tgc_repeated(:), Xt_repeated(:)
        real(rk) :: knot_repeated(9)
        integer :: ii

        allocate(Xc_repeated(6, 3), source=0.0_rk)
        do ii = 1, 6
            Xc_repeated(ii,1) = real(ii - 1, rk)
            Xc_repeated(ii,2) = 0.25_rk*real((ii - 1)**2, rk)
        end do
        knot_repeated = [0.0_rk, 1.0_rk, 2.0_rk, 3.0_rk, 3.0_rk, 3.0_rk, 4.0_rk, 6.0_rk, 9.0_rk]

        call repeated%set(knot_repeated, Xc_repeated, degree=2)
        call repeated%create(res=5)
        Xt_repeated = repeated%get_Xt()
        call repeated%basis(3.25_rk, Tgc_repeated)
        call repeated%err%print()

        call ut%test(ti)%check(&
            name     = "set(): repeated nonuniform non-open curve knot vector",&
            res      = merge(1, 0, repeated%err%ok .and. repeated%get_degree() == 2 .and. repeated%get_nc() == 6 .and. &
                abs(Xt_repeated(1) - 2.0_rk) <= nurbs_curve_tol .and. abs(Xt_repeated(size(Xt_repeated)) - 4.0_rk) <= nurbs_curve_tol .and. &
                abs(sum(Tgc_repeated) - 1.0_rk) <= nurbs_curve_tol),&
            expected = 1,&
            msg      = "Curve should support repeated, nonuniform, non-open knot vectors",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0129


    subroutine forcad_nurbs_curve_0130(ut, ti)
