    subroutine forcad_nurbs_curve_0182(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        type(nurbs_curve) :: rational_order
        real(rk) :: Xc_order(2,3), Wc_order(2), expected_order(2), magnitude
        real(rk), allocatable :: Dgc_order(:)

        Xc_order = 0.0_rk
        Wc_order = [1.0_rk, 2.0_rk]
        call rational_order%set(&
            knot = [0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk],&
            Xc   = Xc_order,&
            Wc   = Wc_order)
        magnitude = 48.0_rk/(1.25_rk**5)
        expected_order = [magnitude,-magnitude]

        call rational_order%derivative_order(&
            Xt    = 0.25_rk,&
            order = 4,&
            Dgc   = Dgc_order)
        call rational_order%err%print()

        call ut%test(ti)%check(&
            name     = "derivative_order(): rational fourth derivative",&
            res      = Dgc_order,&
            expected = expected_order,&
            tol      = 256.0_rk*epsilon(1.0_rk)*magnitude,&
            msg      = "Derivative_order(): rational fourth derivative is incorrect.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0182


    subroutine forcad_nurbs_curve_0183(ut, ti)
