            order = 4,&
            Dgc   = Dgc_order)
        call rational_order%err%print()

        call ut%test(ti)%check(&
            name     = "derivative_order(): differentiated partition",&
            res      = sum(Dgc_order),&
            expected = 0.0_rk,&
            tol      = 256.0_rk*epsilon(1.0_rk)*magnitude,&
            msg      = "Derivative_order(): differentiated partition is incorrect.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0183


    subroutine forcad_nurbs_curve_0184(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        type(nurbs_curve) :: rational_order
        real(rk) :: Xc_order(2,3), Wc_order(2), expected_order(2), magnitude
        real(rk), allocatable :: Dgc_order(:)
        real(rk), allocatable :: Dgc_order_elem(:)

        Xc_order = 0.0_rk
        Wc_order = [1.0_rk, 2.0_rk]
        call rational_order%set(&
            knot = [0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk],&
            Xc   = Xc_order,&
