        boundary_knot = full_break_curve%get_knot()
        call full_break_curve%err%print()

        call ut%test(ti)%check(&
            name     = "new full-break insertion multiplicity",&
            res      = count(abs(boundary_knot - 0.5_rk) <= 16.0_rk*epsilon(1.0_rk)),&
            expected = 3,&
            msg      = "A quadratic full break must have multiplicity three",&
            group    = "forcad_nurbs_curve")
