        real(rk) :: rank_one_knot(6), rank_one_Xc(3), rank_one_Wc(3), expected_Xc(3,3)

        rank_one_knot = [0.0_rk, 0.0_rk, 0.0_rk, 1.0_rk, 1.0_rk, 1.0_rk]
        rank_one_Xc = [0.0_rk, 1.0_rk, 2.0_rk]
        rank_one_Wc = [1.0_rk, 0.75_rk, 1.0_rk]
        expected_Xc = 0.0_rk
        expected_Xc(:,1) = rank_one_Xc

        call rank_one_curve%set(rank_one_knot, rank_one_Xc, rank_one_Wc)

        copied_curve = rank_one_curve
        call rank_one_curve%modify_Xc(5.0_rk, 1, 1)
        call rank_one_curve%err%print()
        call copied_curve%err%print()

        call ut%test(ti)%check(&
            name     = "curve intrinsic assignment deep copy",&
            res      = copied_curve%get_Xc(1,1),&
            expected = 0.0_rk,&
            tol      = 0.0_rk,&
            msg      = "Curve intrinsic assignment deep copy is incorrect.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0253


    subroutine forcad_nurbs_curve_0254(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: knot(8) = [&
            0.0_rk,0.0_rk,0.0_rk,0.5_rk,0.5_rk,1.0_rk,1.0_rk,1.0_rk]
        real(rk), parameter :: Xc(5,3) = reshape([&
            0.0_rk,0.0_rk,1.0_rk,0.0_rk,0.0_rk,&
            0.0_rk,0.0_rk,0.0_rk,0.0_rk,0.0_rk,&
            0.0_rk,0.0_rk,0.0_rk,0.0_rk,0.0_rk], [5,3])
        type(nurbs_curve) :: curve
        real(rk), allocatable :: knot_after(:), Xc_after(:,:)
        logical :: preserved

        call curve%set(knot, Xc)
        call curve%remove_knots([0.5_rk], [1])
        call curve%err%print()

        knot_after = curve%get_knot()
        Xc_after = curve%get_Xc()
        preserved = curve%err%ok .and. size(knot_after) == size(knot) .and. &
            size(Xc_after,1) == size(Xc,1) .and. size(Xc_after,2) == size(Xc,2)
        if (preserved) preserved = maxval(abs(knot_after-knot)) <= epsilon(1.0_rk) .and. &
            maxval(abs(Xc_after-Xc)) <= epsilon(1.0_rk)

        call ut%test(ti)%check(&
            name     = "curve rejects geometry-changing removal",&
            res      = preserved,&
            expected = .true.,&
            msg      = "Curve removal changed nonremovable geometry.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0254


