    subroutine forcad_nurbs_curve_0256(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        character(len=*), parameter :: filename = "vtk/forcad_wrapped_open_curve.iges"
        type(nurbs_curve) :: curve
        real(rk), parameter :: knot(4) = [0.0_rk,0.0_rk,1.0_rk,1.0_rk]
        real(rk), parameter :: Xc(2,2) = reshape([&
            0.0_rk,1.0_rk,0.0_rk,0.0_rk], [2,2])
        character(len=512) :: iges_line
        integer :: iges_unit, ios
        logical :: found

        call curve%set(&
            knot            = knot,&
            Xc              = Xc,&
            degree          = 1,&
            wrap_parameters = .true.)
        call curve%export_iges(filename)
        found = .false.
        open(newunit=iges_unit, file=filename, status="old", action="read", iostat=ios)
        if (ios == 0) then
            do
                read(iges_unit, "(A)", iostat=ios) iges_line
                if (ios /= 0) exit
                if (index(iges_line, "126,1,1,0,0,1,0") > 0) then
                    found = .true.
                    exit
                end if
            end do
            close(iges_unit)
        end if
        open(newunit=iges_unit, file=filename, status="old", iostat=ios)
        if (ios == 0) close(iges_unit, status="delete")
        call curve%err%print()

        call ut%test(ti)%check(&
            name     = "wrapped open curve IGES properties",&
            res      = found,&
            expected = .true.,&
            msg      = "Wrapping must not mark an open curve closed or periodic.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0256


