    subroutine forcad_nurbs_curve_0263(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: tol = 16384.0_rk*epsilon(1.0_rk)
        type(nurbs_curve) :: curve
        real(rk), parameter :: knot(9) = [&
            -2.2_rk,-1.6_rk,0.0_rk,0.7_rk,1.8_rk,2.4_rk,4.0_rk,4.7_rk,5.8_rk]
        real(rk), parameter :: Xc(6,2) = reshape([&
            1.0_rk,0.0_rk,-1.0_rk,0.0_rk,1.0_rk,0.0_rk,&
            0.0_rk,1.0_rk,0.0_rk,-1.0_rk,0.0_rk,1.0_rk], [6,2])
        real(rk), parameter :: Wc(6) = [1.0_rk,1.4_rk,0.8_rk,1.2_rk,1.0_rk,1.4_rk]
        real(rk), parameter :: Xt(6) = [0.0_rk,0.2_rk,0.9_rk,1.9_rk,3.1_rk,4.0_rk]
        real(rk) :: actual(6,2), expected(6,2)
        integer :: i

        call curve%set(&
            knot   = knot,&
            Xc     = Xc,&
            Wc     = Wc,&
            degree = 2)
        do i = 1, size(Xt)
            expected(i,:) = curve%cmp_Xg(Xt(i))
        end do
        call curve%elevate_degree(1)
        do i = 1, size(Xt)
            actual(i,:) = curve%cmp_Xg(Xt(i))
        end do
        call curve%err%print()

        call ut%test(ti)%check(&
            name     = "curve periodic elevation geometry",&
            res      = actual,&
            expected = expected,&
            tol      = tol,&
            msg      = "Periodic degree elevation changed curve geometry.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0263


