    subroutine forcad_nurbs_curve_0265(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: tol = 4096.0_rk*epsilon(1.0_rk)
        type(nurbs_curve) :: curve
        real(rk), parameter :: knot(9) = [&
            -2.2_rk,-1.6_rk,0.0_rk,0.7_rk,1.8_rk,2.4_rk,4.0_rk,4.7_rk,5.8_rk]
        real(rk), parameter :: Xc(6,2) = reshape([&
            1.0_rk,0.0_rk,-1.0_rk,0.0_rk,1.0_rk,0.0_rk,&
            0.0_rk,1.0_rk,0.0_rk,-1.0_rk,0.0_rk,1.0_rk], [6,2])
        real(rk), parameter :: Wc(6) = [1.0_rk,1.4_rk,0.8_rk,1.2_rk,1.0_rk,1.4_rk]
        real(rk), allocatable :: T_start(:), T_end(:), dT_start(:), dT_end(:)
        real(rk) :: folded_start(4,2), folded_end(4,2)
        integer, allocatable :: map(:)
        integer :: i

        call curve%set(&
            knot   = knot,&
            Xc     = Xc,&
            Wc     = Wc,&
            degree = 2)
        call curve%derivative(0.0_rk, dT_start, T_start)
        call curve%derivative(4.0_rk, dT_end, T_end)
        map = curve%cmp_dof_map()
        folded_start = 0.0_rk
        folded_end = 0.0_rk
        do i = 1, size(map)
            folded_start(map(i),1) = folded_start(map(i),1) + T_start(i)
            folded_start(map(i),2) = folded_start(map(i),2) + dT_start(i)
            folded_end(map(i),1) = folded_end(map(i),1) + T_end(i)
            folded_end(map(i),2) = folded_end(map(i),2) + dT_end(i)
        end do
        call curve%err%print()

        call ut%test(ti)%check(&
            name     = "periodic curve seam basis",&
            res      = folded_end,&
            expected = folded_start,&
            tol      = tol,&
            msg      = "Cyclic basis values or seam derivatives do not agree.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0265


    subroutine forcad_nurbs_curve_0266(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: knot(4) = [0.0_rk,0.0_rk,1.0_rk,1.0_rk]
        real(rk), parameter :: Xc(2,2) = 0.0_rk
        type(nurbs_curve) :: curve
        real(rk), allocatable :: Tgc(:), dTgc_dXg(:,:), d2Tgc_dXg2(:)
        real(rk) :: dL

        call curve%set(&
            knot   = knot,&
            Xc     = Xc,&
            degree = 1)
        call curve%ansatz(&
            ie          = 1,&
            ig          = 1,&
            Tgc         = Tgc,&
            dTgc_dXg    = dTgc_dXg,&
            dL          = dL,&
            ngauss      = 1,&
            d2Tgc_dXg2  = d2Tgc_dXg2,&
            strict      = .true.)
        call curve%err%print()

        call ut%test(ti)%check(&
            name     = "strict curve rejects zero tangent",&
            res      = .not. curve%err%ok .and. abs(dL) <= tiny(1.0_rk) .and. &
                maxval(abs(dTgc_dXg)) <= tiny(1.0_rk) .and. &
                maxval(abs(d2Tgc_dXg2)) <= tiny(1.0_rk),&
            expected = .true.,&
            msg      = "Strict ansatz accepted a singular curve tangent.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0266


