    subroutine forcad_nurbs_curve_0269(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: tol = 128.0_rk*epsilon(1.0_rk)
        real(rk), parameter :: knot(4) = [0.0_rk,0.0_rk,1.0_rk,1.0_rk]
        real(rk), parameter :: Xc(2,3) = reshape([&
            0.0_rk,2.0_rk,0.0_rk,0.0_rk,0.0_rk,0.0_rk], [2,3])
        real(rk), parameter :: X(3,1) = reshape([&
            0.0_rk,0.25_rk,1.0_rk], [3,1])
        type(nurbs_curve) :: curve
        real(rk), allocatable :: Xt(:), Xg(:,:)
        integer, allocatable :: elem(:,:)
        real(rk) :: nearest_Xg(3), nearest_Xt
        integer :: id

        call curve%set(&
            knot   = knot,&
            Xc     = Xc,&
            degree = 1)
        call curve%create(res=7)
        call curve%put_to_nurbs(X)
        call curve%nearest_point(&
            point_Xg   = [0.5_rk,0.0_rk,0.0_rk],&
            nearest_Xg = nearest_Xg,&
            nearest_Xt = nearest_Xt,&
            id         = id)
        Xt = curve%get_Xt()
        Xg = curve%get_Xg()
        elem = curve%get_elem_Xg_vis()
        call curve%err%print()

        call ut%test(ti)%check(&
            name     = "put_to_nurbs curve cache replacement",&
            res      = curve%err%ok .and. curve%get_ng() == 3 .and. &
                size(Xt) == 3 .and. all(shape(Xg) == [3,3]) .and. &
                all(shape(elem) == [2,2]) .and. id == 2 .and. &
                maxval(abs(Xt-[0.0_rk,0.25_rk,1.0_rk])) <= tol .and. &
                abs(nearest_Xt-0.25_rk) <= tol .and. &
                maxval(abs(nearest_Xg-[0.5_rk,0.0_rk,0.0_rk])) <= tol,&
            expected = .true.,&
            msg      = "Curve sample parameters and geometry cache are inconsistent.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0269


    subroutine forcad_nurbs_curve_0270(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: tol = 128.0_rk*epsilon(1.0_rk)
        real(rk), parameter :: knot(7) = [&
            0.0_rk,0.0_rk,0.0_rk,0.5_rk,1.0_rk,1.0_rk,1.0_rk]
        real(rk), parameter :: Xt(9) = [&
            0.0_rk,0.125_rk,0.25_rk,0.375_rk,0.5_rk,&
            0.625_rk,0.75_rk,0.875_rk,1.0_rk]
        real(rk), parameter :: Xdata(9,1) = reshape([&
            -0.52613569629176171_rk,-2.7932097690057072_rk,&
            -0.12457766409497265_rk,-1.0921215668918383_rk,&
            -0.10431650515569141_rk,-1.1755376952645962_rk,&
            -2.2127487058295481_rk,0.02135077665918364_rk,&
            -0.26585387032100716_rk], [9,1])
        real(rk), parameter :: Xc(4,1) = reshape([&
            0.0_rk,1.0_rk,2.0_rk,3.0_rk], [4,1])
        type(nurbs_curve) :: curve
        real(rk), allocatable :: Wc(:)
        logical :: fit_failed

        call curve%set(&
            knot   = knot,&
            Xc     = Xc,&
            degree = 2)
        call curve%lsq_fit_nurbs(&
            Xt       = Xt,&
            Xdata    = Xdata,&
            ndata    = 9,&
            maxit    = 2,&
            tol      = 0.0_rk,&
            mu0      = 0.0_rk,&
            reg_logw = 0.0_rk)
        fit_failed = .not. curve%err%ok
        call curve%err%print()
        call curve%err%reset()
        Wc = curve%get_Wc()

        call ut%test(ti)%check(&
            name     = "NURBS fit rejects increasing trial",&
            res      = fit_failed .and. size(Wc) == 4 .and. &
                maxval(abs(Wc-1.0_rk)) <= tol,&
            expected = .true.,&
            msg      = "Increasing rational trial was accepted or not reported.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0270


    subroutine forcad_nurbs_curve_0271(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: tol = 1.0e-12_rk
        real(rk), parameter :: knot(4) = [0.0_rk,0.0_rk,1.0_rk,1.0_rk]
        real(rk), parameter :: Xc(2,1) = reshape([0.0_rk,1.0_rk], [2,1])
        type(nurbs_curve) :: curve
        real(rk) :: nearest_Xt, nearest_Xg(1)

        call curve%set(&
            knot   = knot,&
            Xc     = Xc,&
            degree = 1)
        call curve%nearest_point2(&
            point_Xg   = [-1.0_rk],&
            tol        = tol,&
            maxit      = 5,&
            nearest_Xt = nearest_Xt,&
            nearest_Xg = nearest_Xg)
        call curve%err%print()

        call ut%test(ti)%check(&
            name     = "curve boundary projected stationarity",&
            res      = curve%err%ok .and. abs(nearest_Xt) <= tol .and. &
                abs(nearest_Xg(1)) <= tol,&
            expected = .true.,&
            msg      = "A KKT-stationary curve boundary was not accepted.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0271


    subroutine forcad_nurbs_curve_0272(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: tol = 64.0_rk*epsilon(1.0_rk)
        real(rk), parameter :: breakpoint = 4.0_rk/9.0_rk
        real(rk), parameter :: knot(6) = [&
            0.0_rk,0.0_rk,breakpoint,breakpoint,1.0_rk,1.0_rk]
        real(rk), parameter :: Xc(4,1) = reshape([&
            100.0_rk,100.0_rk,0.0_rk,1.0e-6_rk], [4,1])
        type(nurbs_curve) :: curve
        real(rk) :: nearest_Xt, nearest_Xg(1)
        logical :: line_search_failed

        call curve%set(&
            knot   = knot,&
            Xc     = Xc,&
            degree = 1)
        call curve%nearest_point2(&
            point_Xg   = [-0.1_rk],&
            tol        = 0.0_rk,&
            maxit      = 5,&
            nearest_Xt = nearest_Xt,&
            nearest_Xg = nearest_Xg)
        line_search_failed = .not. curve%err%ok
        call curve%err%print()
        call curve%err%reset()

        call ut%test(ti)%check(&
            name     = "curve Armijo rejection retains iterate",&
            res      = line_search_failed .and. abs(nearest_Xt-breakpoint) <= tol .and. &
                abs(nearest_Xg(1)) <= tol,&
            expected = .true.,&
            msg      = "A failed Armijo search changed the curve iterate.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0272


    subroutine forcad_nurbs_curve_0273(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: tol = 4096.0_rk*epsilon(1.0_rk)
        real(rk), parameter :: knot(4) = [0.0_rk,0.0_rk,1.0_rk,1.0_rk]
        real(rk), parameter :: Xc(2,2) = reshape([&
            0.0_rk,1.0_rk,0.0_rk,0.5_rk], [2,2])
        real(rk), parameter :: Wc(2) = [1.0_rk,2.0_rk]
        type(nurbs_curve) :: reference, small_scale, large_scale
        real(rk), allocatable :: Xg_ref(:), Xg_small(:), Xg_large(:)
        real(rk), allocatable :: T_ref(:), T_small(:), T_large(:)
        real(rk), allocatable :: dT_ref(:), dT_small(:), dT_large(:)
        real(rk), allocatable :: d2T_ref(:), d2T_small(:), d2T_large(:)

        call reference%set(knot=knot, Xc=Xc, Wc=Wc, degree=1)
        call small_scale%set(knot=knot, Xc=Xc, Wc=1.0e-200_rk*Wc, degree=1)
        call large_scale%set(knot=knot, Xc=Xc, Wc=1.0e200_rk*Wc, degree=1)
        Xg_ref = reference%cmp_Xg(0.37_rk)
        Xg_small = small_scale%cmp_Xg(0.37_rk)
        Xg_large = large_scale%cmp_Xg(0.37_rk)
        call reference%derivative2(0.37_rk, d2T_ref, dT_ref, T_ref)
        call small_scale%derivative2(0.37_rk, d2T_small, dT_small, T_small)
        call large_scale%derivative2(0.37_rk, d2T_large, dT_large, T_large)
        call reference%err%print()
        call small_scale%err%print()
        call large_scale%err%print()

        call ut%test(ti)%check(&
            name     = "curve projective-scale invariance",&
            res      = reference%err%ok .and. small_scale%err%ok .and. &
                large_scale%err%ok .and. all(ieee_is_finite(Xg_small)) .and. &
                all(ieee_is_finite(Xg_large)) .and. &
                maxval(abs(Xg_small-Xg_ref)) <= tol .and. &
                maxval(abs(Xg_large-Xg_ref)) <= tol .and. &
                maxval(abs(T_small-T_ref)) <= tol .and. &
                maxval(abs(T_large-T_ref)) <= tol .and. &
                maxval(abs(dT_small-dT_ref)) <= tol .and. &
                maxval(abs(dT_large-dT_ref)) <= tol .and. &
                maxval(abs(d2T_small-d2T_ref)) <= tol .and. &
                maxval(abs(d2T_large-d2T_ref)) <= tol,&
            expected = .true.,&
            msg      = "Curve values changed under a common weight scale.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0273


    subroutine forcad_nurbs_curve_0274(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: tol = 4096.0_rk*epsilon(1.0_rk)
        real(rk), parameter :: knot(4) = [0.0_rk,0.0_rk,1.0_rk,1.0_rk]
        real(rk), parameter :: Xc(2,1) = reshape([0.0_rk,1.0_rk], [2,1])
        real(rk), parameter :: Wc(2) = [1.0_rk,2.0_rk]
        type(nurbs_curve) :: reference, small_scale, large_scale
        real(rk) :: length_ref, length_small, length_large

        call reference%set(knot=knot, Xc=Xc, Wc=Wc, degree=1)
        call small_scale%set(knot=knot, Xc=Xc, Wc=1.0e-200_rk*Wc, degree=1)
        call large_scale%set(knot=knot, Xc=Xc, Wc=1.0e200_rk*Wc, degree=1)
        call reference%cmp_length(length_ref, ngauss=16)
        call small_scale%cmp_length(length_small, ngauss=16)
        call large_scale%cmp_length(length_large, ngauss=16)
        call reference%err%print()
        call small_scale%err%print()
        call large_scale%err%print()

        call ut%test(ti)%check(&
            name     = "curve length weight-scale invariance",&
            res      = reference%err%ok .and. small_scale%err%ok .and. &
                large_scale%err%ok .and. ieee_is_finite(length_ref) .and. &
                ieee_is_finite(length_small) .and. ieee_is_finite(length_large) .and. &
                abs(length_ref-1.0_rk) <= tol .and. &
                abs(length_small-length_ref) <= tol .and. &
                abs(length_large-length_ref) <= tol,&
            expected = .true.,&
            msg      = "Curve length changed under a common weight scale.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0274


    subroutine forcad_nurbs_curve_0275(ut, ti)
        type(unit_tests), intent(inout) :: ut
        integer, intent(inout) :: ti

        real(rk), parameter :: tol = 2.0e-11_rk
        real(rk), parameter :: knot(6) = [&
            0.0_rk,0.0_rk,0.0_rk,1.0_rk,1.0_rk,1.0_rk]
        real(rk), parameter :: Xt(7) = [&
            0.0_rk,0.13_rk,0.31_rk,0.5_rk,0.72_rk,0.91_rk,1.0_rk]
        real(rk), parameter :: Xc(3,2) = reshape([&
            0.0_rk,1.0_rk,2.0_rk,0.0_rk,1.0_rk,0.0_rk], [3,2])
        real(rk), parameter :: Wc(3) = 1.0e-200_rk*[1.0_rk,2.0_rk,1.0_rk]
        type(nurbs_curve) :: curve
        real(rk), allocatable :: Xg_ref(:,:), Xg_insert(:,:), Xg_remove(:,:), Xg_elevate(:,:)
        real(rk), allocatable :: Wc_after(:)

        call curve%set(knot=knot, Xc=Xc, Wc=Wc, degree=2)
        call curve%create(Xt=Xt)
        Xg_ref = curve%get_Xg()
        call curve%insert_knots([0.5_rk], [1])
        call curve%create(Xt=Xt)
        Xg_insert = curve%get_Xg()
        call curve%remove_knots([0.5_rk], [1])
        call curve%create(Xt=Xt)
        Xg_remove = curve%get_Xg()
        call curve%elevate_degree(1)
        call curve%create(Xt=Xt)
        Xg_elevate = curve%get_Xg()
        Wc_after = curve%get_Wc()
        call curve%err%print()

        call ut%test(ti)%check(&
            name     = "curve refinement preserves tiny weights",&
            res      = curve%err%ok .and. all(ieee_is_finite(Xg_elevate)) .and. &
                all(ieee_is_finite(Wc_after)) .and. all(Wc_after > 0.0_rk) .and. &
                maxval(Wc_after) < 1.0e-190_rk .and. &
                maxval(abs(Xg_insert-Xg_ref)) <= tol .and. &
                maxval(abs(Xg_remove-Xg_ref)) <= tol .and. &
                maxval(abs(Xg_elevate-Xg_ref)) <= tol,&
            expected = .true.,&
            msg      = "Curve refinement changed geometry or its weight gauge.",&
            group    = "forcad_nurbs_curve")
        ti = ti + 1

    end subroutine forcad_nurbs_curve_0275


